import { createHmac, timingSafeEqual } from "node:crypto";

export const SDK_KEY_PREFIX = "vx_pk";

// 12 random base64url characters for the indexed id, 43 for the
// 256-bit publishable secret generated by scripts/sdk-license.mjs.
const KEY_RE = /^vx_pk_([A-Za-z0-9_-]{12,32})_([A-Za-z0-9_-]{43})$/;
const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$/;
const DNS_HOST_RE = /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)*[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/;

/** Parse a publishable SDK key without ever logging or retaining it. */
export function parseSdkLicenseKey(value) {
  const match = typeof value === "string" ? KEY_RE.exec(value) : null;
  return match ? { id: match[1], secret: match[2] } : null;
}

/** Extract the key from the sole supported credential shape. */
export function bearerSdkLicenseKey(header) {
  if (typeof header !== "string" || !header.startsWith("Bearer ")) return null;
  return parseSdkLicenseKey(header.slice(7));
}

/**
 * HMAC rather than a plain SHA digest means a database dump alone cannot be
 * used to test guessed secrets. Secrets themselves have 256 bits of entropy,
 * so a deliberately slow password KDF would add latency without useful gain.
 */
export function hashSdkLicenseSecret(id, secret, pepper) {
  if (typeof pepper !== "string" || pepper.length < 32) {
    throw new Error("SDK_LICENSE_PEPPER must contain at least 32 characters");
  }
  return createHmac("sha256", pepper)
    .update(id)
    .update("\0")
    .update(secret)
    .digest("hex");
}

/** Constant-time digest comparison (after a fixed-size decoding check). */
export function verifySdkLicenseSecret(id, secret, storedHash, pepper) {
  let expected;
  try {
    expected = Buffer.from(hashSdkLicenseSecret(id, secret, pepper), "hex");
  } catch {
    return false;
  }
  if (typeof storedHash !== "string" || !/^[0-9a-f]{64}$/i.test(storedHash)) {
    return false;
  }
  const actual = Buffer.from(storedHash, "hex");
  return actual.length === expected.length && timingSafeEqual(actual, expected);
}

function isLoopback(hostname) {
  return (
    hostname === "localhost" ||
    hostname === "127.0.0.1" ||
    hostname === "[::1]"
  );
}

/**
 * Strict browser Origin parser. Production origins must be HTTPS; HTTP is
 * accepted only for loopback development. Paths, credentials and `null`
 * origins are rejected.
 */
export function parseSdkOrigin(value) {
  if (typeof value !== "string" || !value || value === "null") return null;
  let url;
  try {
    url = new URL(value);
  } catch {
    return null;
  }
  const hostname = url.hostname.toLowerCase().replace(/\.$/, "");
  const secure = url.protocol === "https:";
  const local = url.protocol === "http:" && isLoopback(hostname);
  if (
    (!secure && !local) ||
    !hostname ||
    url.username ||
    url.password ||
    url.pathname !== "/" ||
    url.search ||
    url.hash
  ) {
    return null;
  }
  return { origin: url.origin, hostname };
}

/** Normalize an admin-supplied exact domain or `*.` wildcard pattern. */
export function normalizeSdkDomainPattern(input) {
  if (typeof input !== "string") return null;
  let value = input.trim().toLowerCase().replace(/\.$/, "");
  if (value === "[::1]") return value;
  if (!value || /[\s/:?#@]/.test(value)) return null;

  const wildcard = value.startsWith("*.");
  if (wildcard) value = value.slice(2);
  if (!DNS_HOST_RE.test(value)) return null;

  // A wildcard must be anchored below a registrable-looking suffix. This
  // intentionally rejects dangerous entries such as `*.com`.
  if (wildcard && !value.includes(".")) return null;
  return `${wildcard ? "*." : ""}${value}`;
}

/** Daily-rotating, irreversible bucket id for per-client abuse limiting. */
export function sdkRateLimitSubject(
  licenseId,
  networkAddress,
  pepper,
  now = new Date(),
) {
  if (typeof pepper !== "string" || pepper.length < 32) {
    throw new Error("SDK_LICENSE_PEPPER must contain at least 32 characters");
  }
  const day = now.toISOString().slice(0, 10);
  const address = String(networkAddress || "unknown").trim().slice(0, 160);
  return createHmac("sha256", pepper)
    .update("rate\0")
    .update(day)
    .update("\0")
    .update(String(licenseId))
    .update("\0")
    .update(address)
    .digest("hex");
}

export function sdkDomainAllowed(hostname, patterns) {
  const host = String(hostname || "").toLowerCase().replace(/\.$/, "");
  if (!host) return false;
  return patterns.some((raw) => {
    const pattern = normalizeSdkDomainPattern(raw);
    if (!pattern) return false;
    if (!pattern.startsWith("*.")) return host === pattern;
    const suffix = pattern.slice(2);
    // `*.example.com` allows a.example.com and a.b.example.com, but not
    // example.com or evil-example.com.
    return host !== suffix && host.endsWith(`.${suffix}`);
  });
}

/** The body domain is a consistency assertion only; Origin stays authoritative. */
export function sdkRequestDomainMatches(originHostname, requestedDomain) {
  const normalized = normalizeSdkDomainPattern(requestedDomain);
  return Boolean(
    normalized &&
      !normalized.startsWith("*.") &&
      normalized === String(originHostname || "").toLowerCase().replace(/\.$/, ""),
  );
}

export function parseSemver(value) {
  const match = typeof value === "string" ? SEMVER_RE.exec(value) : null;
  if (!match) return null;
  const numbers = [Number(match[1]), Number(match[2]), Number(match[3])];
  if (numbers.some((part) => !Number.isSafeInteger(part))) return null;
  const prerelease = match[4] ? match[4].split(".") : [];
  if (prerelease.some((part) => /^0\d+$/.test(part))) return null;
  return {
    major: numbers[0],
    minor: numbers[1],
    patch: numbers[2],
    prerelease,
  };
}

function comparePrerelease(a, b) {
  if (!a.length && !b.length) return 0;
  if (!a.length) return 1;
  if (!b.length) return -1;
  for (let i = 0; i < Math.max(a.length, b.length); i += 1) {
    if (a[i] === undefined) return -1;
    if (b[i] === undefined) return 1;
    if (a[i] === b[i]) continue;
    const aNumeric = /^\d+$/.test(a[i]);
    const bNumeric = /^\d+$/.test(b[i]);
    if (aNumeric && bNumeric) {
      if (a[i].length !== b[i].length) return a[i].length < b[i].length ? -1 : 1;
      return a[i] < b[i] ? -1 : 1;
    }
    if (aNumeric !== bNumeric) return aNumeric ? -1 : 1;
    return a[i] < b[i] ? -1 : 1;
  }
  return 0;
}

export function compareSemver(left, right) {
  const a = typeof left === "string" ? parseSemver(left) : left;
  const b = typeof right === "string" ? parseSemver(right) : right;
  if (!a || !b) throw new TypeError("Invalid semantic version");
  for (const key of ["major", "minor", "patch"]) {
    if (a[key] !== b[key]) return a[key] < b[key] ? -1 : 1;
  }
  return comparePrerelease(a.prerelease, b.prerelease);
}

export function sdkVersionAllowed(version, minVersion, maxVersion) {
  const current = parseSemver(version);
  const min = parseSemver(minVersion);
  const max = maxVersion ? parseSemver(maxVersion) : null;
  if (!current || !min || (maxVersion && !max)) return false;
  return compareSemver(current, min) >= 0 && (!max || compareSemver(current, max) <= 0);
}

export function sdkCorsHeaders(origin) {
  return {
    "Access-Control-Allow-Origin": origin,
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Allow-Headers": "authorization, content-type",
    "Access-Control-Expose-Headers":
      "retry-after, x-ratelimit-limit, x-ratelimit-remaining",
    "Access-Control-Max-Age": "600",
    "Cache-Control": "no-store",
    Vary: "Origin",
  };
}
